// calcQosBasedOnCapacity calculates the rbd qos parameters based on rbd volume capacity.
func calcQosBasedOnCapacity(
	ctx context.Context,
	rbdVol *rbdVolume,
	param rbdQos,
	baseVolSizeStr string,
) error {
	var (
		err                error
		baseVolSize        int64
		baseQosLimit       int64
		qosPerGB           int64
		finalCalculatedQos int64
	)
	if rbdVol.QosParameters == nil {
		rbdVol.QosParameters = make(map[string]string)
	}

	if baseVolSizeStr == "" {
		baseVolSizeStr = "0"
	}

	baseVolSize, err = strconv.ParseInt(baseVolSizeStr, 10, 64)
	if err != nil {
		return fmt.Errorf("failed to parse baseVolumeSizeBytes %s: %w", baseVolSizeStr, err)
	}
	if baseVolSize < 0 {
		return fmt.Errorf("baseVolumeSizeBytes %d cannot be negative", baseVolSize)
	}
	baseQosLimit, err = strconv.ParseInt(param.rbdBaseQosLimit, 10, 64)
	if err != nil {
		return fmt.Errorf("failed to parse %s %s: %w", param.rbdQosType, param.rbdBaseQosLimit, err)
	}

	// If qosPerGB is not configured, finalCalculatedQos is equal to baseQosLimit
	if param.rbdQosPerGB != "" {
		qosPerGB, err = strconv.ParseInt(param.rbdQosPerGB, 10, 64)
		if err != nil {
			return fmt.Errorf("failed to parse %s %s: %w", param.rbdQosPerGBType, param.rbdQosPerGB, err)
		}

		var (
			calculatedQos       int64
			calculatedIncrement int64
		)
		calculatedQos, err = calcQosBasedOnVolumeSize(rbdVol.VolSize, baseVolSize, qosPerGB)
		if err != nil {
			return fmt.Errorf("calc qos limit failed: %w", err)
		}

		// finalCalculatedQos = baseQosLimit + (VolSize - baseVolSize) * qosPerGB
		finalCalculatedQos, err = calcQosLimit(baseQosLimit, calculatedQos)
		// If finalCalculatedQos overflow, finalCalculatedQos set to max of int64
		if err != nil {
			finalCalculatedQos = int64(^uint64(0) >> 1)
			log.WarningLog(ctx, "final Qos limit calculation overflow: %v", err)
		} else if finalCalculatedQos < 0 {
			// If finalCalculatedQos < 0, finalCalculatedQos set to 0
			finalCalculatedQos = 0
		}
		// If calculatedIncrement = (VolSize - baseVolSize) * qosPerGB < 0, finalCalculatedQos cannot be negative
		calculatedIncrement, err = calcQosLimit(finalCalculatedQos, -baseQosLimit)
		if err == nil && calculatedIncrement < 0 {
			finalCalculatedQos = baseQosLimit
		}
	} else {
		finalCalculatedQos = baseQosLimit
	}
	log.DebugLog(ctx, "rbd image qos %s value is %d", param.rbdQosType, finalCalculatedQos)
	rbdVol.QosParameters[param.rbdQosType] = strconv.FormatInt(finalCalculatedQos, 10)

